/* Call demo_uprotocol_mqtt from a ThreadX application thread after initializing
   NetX/IP and the packet pool. Provide a synchronized Unix-millisecond clock
   and a platform entropy function. Configure broker ACLs for mcu1/AB/0/1/8001.
   The sample publishes to its own subscription and receives the unmodified data. */
#include "nxd_uprotocol.h"
#include <string.h>

UINT demo_uprotocol_mqtt(NX_IP *ip, NX_PACKET_POOL *pool, NXD_ADDRESS *broker,
                         NXD_UPROTOCOL_CLOCK clock, VOID *clock_context,
                         UINT (*random_bytes)(UCHAR *buffer, UINT size));

/* Example state is static to keep the application thread's stack small. */
static NXD_MQTT_CLIENT demo_mqtt;
static NXD_UPROTOCOL_CLIENT demo_transport;
static ULONG demo_mqtt_stack[4096];
static volatile UINT demo_received;

/* Replace this callback with application processing. Copy data if retaining it. */
static VOID demo_listener(const NXD_UPROTOCOL_MESSAGE *message, VOID *context)
{
    NX_PARAMETER_NOT_USED(context);
    if (message -> payload_length == 5 && memcmp(message -> payload, "hello", 5) == 0)
    {
        demo_received++;
    }
}

/* Return a UCode; inspect demo_transport.last_mqtt_status for MQTT diagnostics. */
UINT demo_uprotocol_mqtt(NX_IP *ip, NX_PACKET_POOL *pool, NXD_ADDRESS *broker,
                         NXD_UPROTOCOL_CLOCK clock, VOID *clock_context,
                         UINT (*random_bytes)(UCHAR *buffer, UINT size))
{
NXD_UPROTOCOL_CONFIG config;
NXD_UPROTOCOL_MESSAGE message;
NXD_UPROTOCOL_URI topic;
UCHAR entropy[10];
UCHAR receive_buffer[256];
UINT status;
UINT i;
UINT created = 0;
    if (broker == NX_NULL || clock == NX_NULL || random_bytes == NX_NULL)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    demo_received = 0;
    status = nxd_mqtt_client_create(&demo_mqtt, "uProtocol demo", "threadx-up-demo", 15,
               ip, pool, demo_mqtt_stack, sizeof(demo_mqtt_stack), 2, NX_NULL, 0);
    if (status)
    {
        return(NXD_UPROTOCOL_UNAVAILABLE);
    }
    memset(&config, 0, sizeof(config));
    nxd_uprotocol_uri_parse("up://mcu1/AB/1/0", &config.local_uri);
    config.server = *broker;
    config.port = 1883;
    config.keepalive = 30;
    config.clean_start = 1;
    config.session_expiry = 0;
    config.maximum_packet_size = 4096;
    config.clock = clock;
    config.clock_context = clock_context;
    status = nxd_uprotocol_create(&demo_transport, &demo_mqtt, &config);
    if (!status)
    {
        created = 1;
        status = nxd_uprotocol_connect(&demo_transport, 5u * NX_IP_PERIODIC_RATE);
    }
    nxd_uprotocol_uri_parse("up://mcu1/AB/1/8001", &topic);
    if (!status)
    {
        status = nxd_uprotocol_register_listener(&demo_transport, &topic, NX_NULL,
                                                  demo_listener, NX_NULL, 5u * NX_IP_PERIODIC_RATE);
    }
    memset(&message, 0, sizeof(message));
    if (!status && random_bytes(entropy, sizeof(entropy)))
    {
        status = NXD_UPROTOCOL_INTERNAL;
    }
    if (!status)
    {
        status = nxd_uprotocol_uuid_create(&message.id, clock(clock_context), entropy);
        message.type = NXD_UPROTOCOL_PUBLISH;
        message.source = topic;
        message.priority = NXD_UPROTOCOL_CS1;
        message.present = NXD_UPROTOCOL_HAS_TTL;
        message.ttl = 10000;
        message.payload_format = NXD_UPROTOCOL_PAYLOAD_TEXT;
        message.payload = (const UCHAR *)"hello";
        message.payload_length = 5;
    }
    if (!status)
    {
        status = nxd_uprotocol_send(&demo_transport, &message, 5u * NX_IP_PERIODIC_RATE);
    }
    for (i = 0; !status && !demo_received && i < 500u; i++)
    {
        status = nxd_uprotocol_process(&demo_transport, receive_buffer, sizeof(receive_buffer), NX_IP_PERIODIC_RATE);
        if (status == NXD_UPROTOCOL_NOT_FOUND || status == NXD_UPROTOCOL_UNAVAILABLE)
        {
            status = 0;
        }
        tx_thread_sleep((NX_IP_PERIODIC_RATE + 99u) / 100u);
    }
    if (!status && !demo_received)
    {
        status = NXD_UPROTOCOL_DEADLINE_EXCEEDED;
    }
    if (created)
    {
        nxd_uprotocol_delete(&demo_transport);
    }
    nxd_mqtt_client_delete(&demo_mqtt);
    return(status);
}
